SELECT Url
FROM attachmentlist
WHERE id = #{id}

SELECT al.*, ai.unit AS unit_name, ai.name AS asset_name FROM AttachmentList al LEFT JOIN asset_info ai ON al.assetId = ai.id
AND ai.unit LIKE CONCAT('%',#{unit},'%') AND al.atName LIKE CONCAT('%',#{atName},'%') AND al.Type = #{type} AND al.updatedTime LIKE CONCAT('%',#{updatedTime},'%') AND al.Status = #{status}
ORDER BY al.id DESC
